// Custom OpenNext entrypoint: forwards HTTP requests and runs scheduled search indexing.
 // @ts-expect-error Generated by opennextjs-cloudflare build.
import openNextWorker from "./.open-next/worker.js";
import { createClient } from "@supabase/supabase-js";
import { refreshYouTubeAccessToken, uploadYouTubeVideo } from "./lib/social/youtube-publisher";

type Env = {
  NEXT_PUBLIC_SUPABASE_URL: string;
  SUPABASE_SERVICE_ROLE_KEY: string;
  BULKSMSBD_API_KEY?: string;
  BULKSMSBD_SENDER_ID?: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  YOUTUBE_TOKEN_ENCRYPTION_KEY?: string;
  AI: {
    run(model: string, input: { text: string[] }): Promise<{ data?: number[][] }>;
  };
};

type ScheduledController = {
  cron: string;
  scheduledTime: number;
};

type ExecutionContextLike = {
  waitUntil(promise: Promise<unknown>): void;
};

type SearchJob = {
  job_id: string;
  product_id: string;
  attempts: number;
  lease_token: string;
};

type Product = {
  id: string;
  name: string;
  description: string | null;
  sku: string | null;
  is_active: boolean;
};

async function processSearchEmbeddingQueue(env: Env): Promise<void> {
  if (!env.NEXT_PUBLIC_SUPABASE_URL || !env.SUPABASE_SERVICE_ROLE_KEY) {
    throw new Error("Search embedding gate is missing Supabase bindings.");
  }
  const gateClient = createClient(env.NEXT_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data: leaseToken, error: gateError } = await gateClient.rpc(
    "neweix_acquire_search_embedding_gate",
    { p_min_interval_seconds: 30, p_lease_seconds: 600 },
  );
  if (gateError) throw new Error(`Search embedding gate failed: ${gateError.message}`);
  if (typeof leaseToken !== "string") {
    console.log("[search-cron] batch skipped by global concurrency/rate gate");
    return;
  }

  try {
    await processSearchEmbeddingQueueBatch(env);
  } finally {
    const { error: releaseError } = await gateClient.rpc(
      "neweix_release_search_embedding_gate",
      { p_lease_token: leaseToken },
    );
    if (releaseError) {
      console.error("[search-cron] global gate release failed", releaseError.message);
    }
  }
}

async function processSearchEmbeddingQueueBatch(env: Env): Promise<void> {
  if (!env.NEXT_PUBLIC_SUPABASE_URL || !env.SUPABASE_SERVICE_ROLE_KEY || !env.AI) {
    throw new Error("Search embedding cron is missing required bindings.");
  }

  const supabase = createClient(env.NEXT_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  const { data: jobs, error: claimError } = await supabase.rpc(
    "neweix_claim_search_embedding_jobs_v2",
    { p_limit: 10 },
  );
  if (claimError) throw new Error(`Queue claim failed: ${claimError.message}`);
  if (!Array.isArray(jobs) || jobs.length === 0) {
    console.log("[search-cron] queue empty");
    return;
  }

  const typedJobs = jobs as SearchJob[];
  const { data: products, error: productsError } = await supabase
    .from("products")
    .select("id,name,description,sku,is_active")
    .in("id", typedJobs.map((job) => job.product_id));

  if (productsError) {
    await Promise.all(typedJobs.map((job) =>
      supabase.rpc("neweix_fail_search_embedding_job_v2", {
        p_job_id: job.job_id,
        p_lease_token: job.lease_token,
        p_error: productsError.message,
      }),
    ));
    throw new Error(`Product lookup failed: ${productsError.message}`);
  }

  const productById = new Map<string, Product>(
    ((products ?? []) as Product[]).map((product) => [product.id, product]),
  );
  const activeJobs = typedJobs.filter((job) => productById.get(job.product_id)?.is_active === true);

  for (const job of typedJobs) {
    if (!activeJobs.some((active) => active.job_id === job.job_id)) {
      const { error } = await supabase.rpc("neweix_complete_search_embedding_job_v2", {
        p_job_id: job.job_id,
        p_lease_token: job.lease_token,
      });
      if (error) console.error("[search-cron] stale job cleanup failed", job.job_id, error.message);
    }
  }

  if (activeJobs.length === 0) {
    console.log("[search-cron] removed inactive product jobs", typedJobs.length);
    return;
  }

  const texts = activeJobs.map((job) => {
    const product = productById.get(job.product_id)!;
    return [
      product.name,
      product.sku ? `SKU ${product.sku}` : "",
      product.description ?? "",
    ].filter(Boolean).join(". ").slice(0, 2000);
  });

  let vectors: number[][] | undefined;
  try {
    const result = await env.AI.run("@cf/baai/bge-m3", { text: texts });
    vectors = result.data;
  } catch (error) {
    const message = error instanceof Error ? error.message : "Workers AI embedding failed";
    await Promise.all(activeJobs.map((job) =>
      supabase.rpc("neweix_fail_search_embedding_job_v2", {
        p_job_id: job.job_id,
        p_lease_token: job.lease_token,
        p_error: message,
      }),
    ));
    throw error;
  }

  if (
    !Array.isArray(vectors) ||
    vectors.length !== activeJobs.length ||
    vectors.some((vector) =>
      !Array.isArray(vector) || vector.length !== 1024 || !vector.every(Number.isFinite),
    )
  ) {
    await Promise.all(activeJobs.map((job) =>
      supabase.rpc("neweix_fail_search_embedding_job_v2", {
        p_job_id: job.job_id,
        p_lease_token: job.lease_token,
        p_error: "Workers AI returned an invalid 1024-dimensional embedding response",
      }),
    ));
    throw new Error("Workers AI returned an invalid embedding response.");
  }

  let indexed = 0;
  let failed = 0;
  for (let index = 0; index < activeJobs.length; index += 1) {
    const job = activeJobs[index];
    const vector = vectors[index];
    const { data: saved, error: saveError } = await supabase.rpc(
      "neweix_save_search_embedding",
      {
        p_job_id: job.job_id,
        p_product_id: job.product_id,
        p_lease_token: job.lease_token,
        p_embedding: `[${vector.join(",")}]`,
        p_model: "@cf/baai/bge-m3",
      },
    );

    if (saveError) {
      await supabase.rpc("neweix_fail_search_embedding_job_v2", {
        p_job_id: job.job_id,
        p_lease_token: job.lease_token,
        p_error: saveError.message,
      });
      failed += 1;
      continue;
    }
    if (saved !== true) {
      // The lease was superseded or the product was removed/deactivated.
      // A stale worker must never write an embedding or mutate the new lease.
      failed += 1;
      continue;
    }
    indexed += 1;
  }

  console.log("[search-cron] batch complete", {
    processed: typedJobs.length,
    indexed,
    failed,
    model: "@cf/baai/bge-m3",
  });
}


type CustomerNotificationJob = {
  id: string;
  phone: string;
  message: string;
  attempts: number;
  lease_token: string;
};

function normalizeBulkSmsPhone(phone: string): string | null {
  let digits = phone.replace(/\\D/g, "");
  if (digits.startsWith("00880")) digits = digits.slice(2);
  if (digits.startsWith("01")) digits = `88${digits}`;
  return /^8801[3-9]\\d{8}$/.test(digits) ? digits : null;
}

function getBulkSmsResponseCode(raw: string): number | null {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed === "number" || typeof parsed === "string") {
      const code = Number(parsed);
      return Number.isFinite(code) ? code : null;
    }
    if (parsed && typeof parsed === "object") {
      const record = parsed as Record<string, unknown>;
      const value = record.response_code ?? record.code ?? record.status;
      const code = Number(value);
      return Number.isFinite(code) ? code : null;
    }
  } catch {
    // BulkSMSBD commonly returns a plain numeric code.
  }
  const match = raw.match(/^\\s*(\\d{3,4})\\b/);
  return match ? Number(match[1]) : null;
}

async function processCustomerNotificationQueue(env: Env): Promise<void> {
  if (!env.NEXT_PUBLIC_SUPABASE_URL || !env.SUPABASE_SERVICE_ROLE_KEY) {
    throw new Error("Customer SMS queue is missing Supabase bindings.");
  }
  if (!env.BULKSMSBD_API_KEY || !env.BULKSMSBD_SENDER_ID) {
    throw new Error("Customer SMS queue is missing BulkSMSBD credentials.");
  }

  const supabase = createClient(env.NEXT_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data: jobs, error: claimError } = await supabase.rpc(
    "neweix_claim_customer_notifications_v2",
    { p_limit: 10 },
  );
  if (claimError) throw new Error(`Customer SMS queue claim failed: ${claimError.message}`);
  if (!Array.isArray(jobs) || jobs.length === 0) return;

  let sent = 0;
  let failed = 0;
  for (const job of jobs as CustomerNotificationJob[]) {
    const number = normalizeBulkSmsPhone(job.phone);
    if (!number) {
      await supabase.rpc("neweix_fail_customer_notification_v2", {
        p_id: job.id,
        p_lease_token: job.lease_token,
        p_error: "Invalid Bangladesh phone number",
      });
      failed += 1;
      continue;
    }

    try {
      const form = new FormData();
      form.set("api_key", env.BULKSMSBD_API_KEY);
      form.set("type", "text");
      form.set("number", number);
      form.set("senderid", env.BULKSMSBD_SENDER_ID);
      form.set("message", job.message.slice(0, 500));

      const response = await fetch("https://bulksmsbd.net/api/smsapi", {
        method: "POST",
        body: form,
        signal: AbortSignal.timeout(12_000),
      });
      const raw = (await response.text()).trim();
      const responseCode = getBulkSmsResponseCode(raw);
      const accepted = response.ok &&
        (responseCode === 202 || (response.status === 202 && responseCode === null));

      if (!accepted) {
        await supabase.rpc("neweix_fail_customer_notification_v2", {
          p_id: job.id,
          p_lease_token: job.lease_token,
          p_error: `BulkSMSBD rejected request (HTTP ${response.status}, code ${responseCode ?? "unknown"})`,
        });
        failed += 1;
        continue;
      }

      const { error: completeError } = await supabase.rpc(
        "neweix_complete_customer_notification_v2",
        { p_id: job.id, p_lease_token: job.lease_token },
      );
      if (completeError) {
        await supabase.rpc("neweix_fail_customer_notification_v2", {
          p_id: job.id,
          p_lease_token: job.lease_token,
          p_error: completeError.message,
        });
        failed += 1;
        continue;
      }
      sent += 1;
    } catch (error) {
      await supabase.rpc("neweix_fail_customer_notification_v2", {
        p_id: job.id,
        p_lease_token: job.lease_token,
        p_error: error instanceof Error ? error.message : "BulkSMSBD network failure",
      });
      failed += 1;
    }
  }
  console.log("[customer-sms-cron] batch complete", { processed: jobs.length, sent, failed });
}


async function processEixPayIntegrityWatchdog(env: Env): Promise<void> {
  if (!env.NEXT_PUBLIC_SUPABASE_URL || !env.SUPABASE_SERVICE_ROLE_KEY) {
    throw new Error("EixPay integrity watchdog is missing Supabase bindings.");
  }

  const supabase = createClient(env.NEXT_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data, error } = await supabase.rpc("eixpay_verify_integrity_watchdog");
  if (error) {
    throw new Error(`EixPay integrity verification failed: ${error.message}`);
  }

  const result = data as {
    valid?: boolean;
    checked_events?: number;
    failure_reason?: string | null;
    first_invalid_sequence?: number | null;
    watchdog_run_id?: number;
    independent_signature?: boolean;
  } | null;

  if (!result?.valid) {
    console.error("[eixpay-integrity-watchdog] INTEGRITY FAILURE", {
      checkedEvents: result?.checked_events ?? 0,
      failureReason: result?.failure_reason ?? "UNKNOWN",
      firstInvalidSequence: result?.first_invalid_sequence ?? null,
      watchdogRunId: result?.watchdog_run_id ?? null,
    });
    return;
  }

  console.log("[eixpay-integrity-watchdog] verification passed", {
    checkedEvents: result.checked_events ?? 0,
    watchdogRunId: result.watchdog_run_id ?? null,
    independentSignature: result.independent_signature === true,
  });
}

type ScheduledSocialPost = {
  id: string;
  title: string;
  caption: string;
  media_urls: string[];
  post_targets: string[];
};

type ConnectedYouTubeAccount = {
  id: string;
  external_account_id: string;
  refresh_token_ciphertext: string;
};

async function processSocialPublishingQueue(env: Env): Promise<void> {
  if (!env.NEXT_PUBLIC_SUPABASE_URL || !env.SUPABASE_SERVICE_ROLE_KEY) {
    throw new Error("Social publishing queue is missing Supabase bindings.");
  }
  if (!env.GOOGLE_CLIENT_ID || !env.GOOGLE_CLIENT_SECRET || !env.YOUTUBE_TOKEN_ENCRYPTION_KEY) {
    throw new Error("YouTube publishing is missing Google OAuth or token encryption secrets.");
  }

  const supabase = createClient(env.NEXT_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data: posts, error: claimError } = await supabase.rpc(
    "neweix_claim_social_posts",
    { p_limit: 5 },
  );
  if (claimError) throw new Error(`Social queue claim failed: ${claimError.message}`);
  if (!Array.isArray(posts) || posts.length === 0) return;

  let published = 0;
  let failed = 0;
  for (const post of posts as ScheduledSocialPost[]) {
    const targets = Array.isArray(post.post_targets) ? post.post_targets : [];
    let postPublished = 0;

    for (const platform of targets) {
      if (platform !== "youtube") {
        await supabase.from("social_media_deliveries").upsert({
          post_id: post.id,
          platform,
          status: "blocked",
          attempt_count: 0,
          last_error: "Automatic publishing for this platform is not enabled yet.",
          updated_at: new Date().toISOString(),
        }, { onConflict: "post_id,platform" });
        continue;
      }

      const { data: account, error: accountError } = await supabase
        .from("social_media_accounts")
        .select("id,external_account_id,refresh_token_ciphertext")
        .eq("platform", "youtube")
        .eq("connection_status", "connected")
        .limit(1)
        .maybeSingle();

      if (accountError || !account?.refresh_token_ciphertext) {
        await supabase.from("social_media_deliveries").upsert({
          post_id: post.id,
          platform,
          status: "failed",
          attempt_count: 1,
          last_error: accountError?.message || "No connected YouTube channel with a refresh token.",
          updated_at: new Date().toISOString(),
        }, { onConflict: "post_id,platform" });
        failed += 1;
        continue;
      }

      const youtubeAccount = account as ConnectedYouTubeAccount;
      const videoUrl = Array.isArray(post.media_urls) ? post.media_urls[0] : "";
      if (!videoUrl) {
        await supabase.from("social_media_deliveries").upsert({
          post_id: post.id,
          account_id: youtubeAccount.id,
          platform,
          status: "failed",
          attempt_count: 1,
          last_error: "A public HTTPS video URL is required for YouTube publishing.",
          updated_at: new Date().toISOString(),
        }, { onConflict: "post_id,platform" });
        failed += 1;
        continue;
      }

      await supabase.from("social_media_deliveries").upsert({
        post_id: post.id,
        account_id: youtubeAccount.id,
        platform,
        status: "processing",
        attempt_count: 1,
        last_error: null,
        updated_at: new Date().toISOString(),
      }, { onConflict: "post_id,platform" });

      try {
        const refreshed = await refreshYouTubeAccessToken(
          youtubeAccount.refresh_token_ciphertext,
          {
            clientId: env.GOOGLE_CLIENT_ID,
            clientSecret: env.GOOGLE_CLIENT_SECRET,
            encryptionKey: env.YOUTUBE_TOKEN_ENCRYPTION_KEY,
          },
        );
        await supabase.from("social_media_accounts").update({
          access_token_ciphertext: refreshed.accessTokenCiphertext,
          token_expires_at: refreshed.expiresAt,
          last_error: null,
          updated_at: new Date().toISOString(),
        }).eq("id", youtubeAccount.id);

        const result = await uploadYouTubeVideo({
          accessToken: refreshed.accessToken,
          videoUrl,
          title: post.title,
          description: post.caption,
        });
        const { error: deliveryError } = await supabase.from("social_media_deliveries").update({
          status: "published",
          provider_post_id: result.videoId,
          provider_url: result.videoUrl,
          published_at: new Date().toISOString(),
          last_error: null,
          updated_at: new Date().toISOString(),
        }).eq("post_id", post.id).eq("platform", platform);
        if (deliveryError) throw deliveryError;
        postPublished += 1;
        published += 1;
      } catch (error) {
        const message = error instanceof Error ? error.message : "YouTube publishing failed.";
        await supabase.from("social_media_deliveries").update({
          status: "failed",
          last_error: message.slice(0, 1000),
          updated_at: new Date().toISOString(),
        }).eq("post_id", post.id).eq("platform", platform);
        const tokenExpired = message.toLowerCase().includes("invalid_grant");
        await supabase.from("social_media_accounts").update({
          ...(tokenExpired ? { connection_status: "expired" } : {}),
          last_error: message.slice(0, 1000),
          updated_at: new Date().toISOString(),
        }).eq("id", youtubeAccount.id);
        failed += 1;
      }
    }

    const finalStatus = postPublished === targets.length
      ? "published"
      : postPublished > 0
        ? "partial"
        : "failed";
    await supabase.from("social_media_posts").update({
      status: finalStatus,
      published_at: postPublished > 0 ? new Date().toISOString() : null,
      updated_at: new Date().toISOString(),
    }).eq("id", post.id);
  }
  console.log("[social-publishing-cron] batch complete", { processed: posts.length, published, failed });
}

type HtmlRewriterElementLike = {
  setAttribute(name: string, value: string): void;
};

type HtmlRewriterLike = {
  on(
    selector: string,
    handlers: { element(element: HtmlRewriterElementLike): void },
  ): HtmlRewriterLike;
  transform(response: Response): Response;
};

function applyHtmlContentSecurityPolicy(response: Response): Response {
  const contentType = response.headers.get("content-type")?.toLowerCase() ?? "";
  if (!contentType.includes("text/html")) return response;

  const nonceBytes = crypto.getRandomValues(new Uint8Array(18));
  let nonceBinary = "";
  for (const byte of nonceBytes) nonceBinary += String.fromCharCode(byte);
  const nonce = btoa(nonceBinary);

  const policy = [
    "default-src 'self'",
    "base-uri 'self'",
    "object-src 'none'",
    "frame-ancestors 'none'",
    "form-action 'self' https://accounts.google.com",
    `script-src 'self' 'nonce-${nonce}' https://challenges.cloudflare.com`,
    "script-src-attr 'none'",
    "style-src 'self' 'unsafe-inline' https:",
    "img-src 'self' data: blob: https:",
    "font-src 'self' data: https:",
    "connect-src 'self' https://grhybvlhdnzlopwbaqun.supabase.co https://challenges.cloudflare.com wss://grhybvlhdnzlopwbaqun.supabase.co",
    "frame-src 'self' https://challenges.cloudflare.com https://www.youtube-nocookie.com https://www.youtube.com https://accounts.google.com",
    "worker-src 'self' blob:",
    "upgrade-insecure-requests",
  ].join("; ");

  const Rewriter = (globalThis as unknown as {
    HTMLRewriter?: new () => HtmlRewriterLike;
  }).HTMLRewriter;

  if (!Rewriter) {
    console.error("[security] Cloudflare HTMLRewriter is unavailable; refusing to serve unprotected HTML.");
    return new Response("Security response processing is unavailable.", {
      status: 503,
      headers: { "Cache-Control": "no-store" },
    });
  }

  const rewritten = new Rewriter()
    .on("script", {
      element(element) {
        element.setAttribute("nonce", nonce);
      },
    })
    .transform(response);

  const headers = new Headers(rewritten.headers);
  // The HTML body changed, so any origin validators or byte lengths are stale.
  headers.delete("Content-Length");
  headers.delete("Content-Encoding");
  headers.delete("Content-MD5");
  headers.delete("ETag");
  headers.delete("Last-Modified");
  headers.delete("Accept-Ranges");
  headers.set("Content-Security-Policy", policy);
  headers.set("Cache-Control", "private, no-store, max-age=0");
  headers.set("X-Content-Type-Options", "nosniff");
  headers.set("X-Frame-Options", "DENY");
  headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
  headers.set("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
  headers.set("Strict-Transport-Security", "max-age=31536000");

  return new Response(rewritten.body, {
    status: rewritten.status,
    statusText: rewritten.statusText,
    headers,
  });
}

export default {
  async fetch(
    request: Request,
    env: Env,
    ctx: ExecutionContextLike,
  ): Promise<Response> {
    const response = await openNextWorker.fetch(request, env, ctx);
    return applyHtmlContentSecurityPolicy(response);
  },
  async scheduled(
    controller: ScheduledController,
    env: Env,
    _ctx: ExecutionContextLike,
  ): Promise<void> {
    console.log("[neweix-cron] started", controller.cron, new Date(controller.scheduledTime).toISOString());
    const tasks: Promise<void>[] = [];
    if (controller.cron === "*/5 * * * *") {
      tasks.push(processCustomerNotificationQueue(env));
      tasks.push(processSearchEmbeddingQueue(env));
    }
    if (controller.cron === "*/15 * * * *") {
      tasks.push(processSocialPublishingQueue(env));
    }
    if (controller.cron === "17 2 * * *") {
      tasks.push(processEixPayIntegrityWatchdog(env));
    }
    const results = await Promise.allSettled(tasks);
    for (const result of results) {
      if (result.status === "rejected") {
        console.error("[neweix-cron] task failed", result.reason instanceof Error ? result.reason.message : "unknown error");
      }
    }
  },
};

